-- ============================================================================
-- Migration 037: M23 Calendar — V1 (háttér + admin)
-- ============================================================================
-- Spec: modules/23_Calendar/01_Funkcionalis_Specifikacio.md (V0.2) 8., 9., 11. fejezet
-- Terv: modules/23_Calendar/02_Megvalositasi_Terv.md 4.1
--
-- 1. M00-bővítés: európai országok, időzónák, országonkénti fő időzóna (NyK-02, NyK-15)
-- 2. Naptár-törzstáblák: időszaktípusok, címkék, időszak-definíciók, előfordulások, definíció–címke
-- 3. Szabálymotor (húsvét, rögzített nap, n-edik hétköznap) és idempotens generálás
-- 4. RLS: publikus olvasás (aktív definíciók, generated/verified előfordulások), írás csak admin
-- 5. Seed: típusok, címkék, évszakok, HU (Mt., NGM-munkarend, tanévrend), Európa (Nager.Date, MIT)
--
-- Idempotens: IF NOT EXISTS, ON CONFLICT DO NOTHING, CREATE OR REPLACE, DROP POLICY IF EXISTS.
-- A seed a meglévő (admin által szerkesztett) sorokat nem írja felül.
-- ============================================================================

BEGIN;

-- ============================================================================
-- 1. M00-bővítés
-- ============================================================================

ON CONFLICT (code) DO NOTHING;

ON CONFLICT (code) DO NOTHING;

  -- F-04: a törzsben szerepel, de nem választható (üzleti döntés: K-03)
  ('BY', 'BLR', '112', 'Belarus',       'Belarusz',      'Belarus',         'Беларусь',           'Europe', 'Eastern Europe',  '+375', 'BYN', 'be', '🇧🇾', false, false, false, NULL, NULL, 52, false),
  ('RU', 'RUS', '643', 'Russia',        'Oroszország',   'Russland',        'Россия',             'Europe', 'Eastern Europe',  '+7',   'RUB', 'ru', '🇷🇺', false, false, false, NULL, NULL, 53, false)
ON CONFLICT (code) DO NOTHING;

ON CONFLICT (tz_id) DO NOTHING;

ALTER TABLE public.ref_countries ADD COLUMN IF NOT EXISTS primary_timezone varchar(50);
DO $$ BEGIN
  ALTER TABLE public.ref_countries
    ADD CONSTRAINT fk_ref_countries_primary_timezone
    FOREIGN KEY (primary_timezone) REFERENCES public.ref_timezones(tz_id);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON COLUMN public.ref_countries.primary_timezone IS
  'M23: az ország fő IANA-időzónája (NyK-15). NULL = nincs meghatározva; a fogyasztó ekkor UTC-t használ. V1: az európai országok kitöltve.';

-- Csak üres értéket tölt (az admin későbbi módosítását nem írja felül).
UPDATE public.ref_countries c
SET primary_timezone = v.tz
FROM (VALUES
  ('AD','Europe/Andorra'), ('AL','Europe/Tirane'), ('AT','Europe/Vienna'), ('BA','Europe/Sarajevo'),
  ('BE','Europe/Brussels'), ('BG','Europe/Sofia'), ('BY','Europe/Minsk'), ('CH','Europe/Zurich'),
  ('CY','Asia/Nicosia'), ('CZ','Europe/Prague'), ('DE','Europe/Berlin'), ('DK','Europe/Copenhagen'),
  ('EE','Europe/Tallinn'), ('ES','Europe/Madrid'), ('FI','Europe/Helsinki'), ('FR','Europe/Paris'),
  ('GB','Europe/London'), ('GR','Europe/Athens'), ('HR','Europe/Zagreb'), ('HU','Europe/Budapest'),
  ('IE','Europe/Dublin'), ('IS','Atlantic/Reykjavik'), ('IT','Europe/Rome'), ('LI','Europe/Vaduz'),
  ('LT','Europe/Vilnius'), ('LU','Europe/Luxembourg'), ('LV','Europe/Riga'), ('MC','Europe/Monaco'),
  ('MD','Europe/Chisinau'), ('ME','Europe/Podgorica'), ('MK','Europe/Skopje'), ('MT','Europe/Malta'),
  ('NL','Europe/Amsterdam'), ('NO','Europe/Oslo'), ('PL','Europe/Warsaw'), ('PT','Europe/Lisbon'),
  ('RO','Europe/Bucharest'), ('RS','Europe/Belgrade'), ('RU','Europe/Moscow'), ('SE','Europe/Stockholm'),
  ('SI','Europe/Ljubljana'), ('SK','Europe/Bratislava'), ('SM','Europe/San_Marino'), ('UA','Europe/Kyiv'),
  ('VA','Europe/Vatican')
) AS v(code, tz)
WHERE c.code = v.code AND c.primary_timezone IS NULL;

-- ============================================================================
-- 2. Segédfüggvények (a táblák CHECK-jei és az RLS használja)
-- ============================================================================

-- Admin-e a hívó (admin_roles, aktív). SECURITY DEFINER: az admin_roles RLS-e csak a saját sort mutatja.
CREATE OR REPLACE FUNCTION public.is_calendar_admin()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.admin_roles r
    WHERE r.user_id = auth.uid() AND r.is_active
  );
$$;
REVOKE ALL ON FUNCTION public.is_calendar_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_calendar_admin() TO anon, authenticated, service_role;

-- Lokalizált név: objektum, nem üres hu és en kulccsal.
CREATE OR REPLACE FUNCTION public.calendar_label_valid(p_label jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  SELECT p_label IS NOT NULL
    AND jsonb_typeof(p_label) = 'object'
    AND length(trim(coalesce(p_label->>'hu', ''))) > 0
    AND length(trim(coalesce(p_label->>'en', ''))) > 0;
$$;

-- A szabály paramétereinek alakja (FR-M23-003; F-01, F-02 kiterjesztés).
CREATE OR REPLACE FUNCTION public.calendar_rule_params_valid(p_kind text, p_params jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE
  v_month int; v_day int; v_end_month int; v_end_day int; v_weekday int; v_n int; v_offset int;
BEGIN
  IF p_params IS NULL OR jsonb_typeof(p_params) <> 'object' THEN RETURN false; END IF;
  IF p_kind = 'explicit' THEN RETURN true; END IF;
  BEGIN
    IF p_kind = 'fixed_annual' THEN
      v_month := (p_params->>'month')::int; v_day := (p_params->>'day')::int;
      IF v_month IS NULL OR v_month NOT BETWEEN 1 AND 12 OR v_day IS NULL OR v_day NOT BETWEEN 1 AND 31 THEN
        RETURN false;
      END IF;
      IF (p_params ? 'end_month') <> (p_params ? 'end_day') THEN RETURN false; END IF;
      IF p_params ? 'end_month' THEN
        v_end_month := (p_params->>'end_month')::int; v_end_day := (p_params->>'end_day')::int;
        IF v_end_month IS NULL OR v_end_day IS NULL
          OR v_end_month NOT BETWEEN 1 AND 12 OR v_end_day NOT BETWEEN 1 AND 31 THEN RETURN false; END IF;
      END IF;
      RETURN true;
    ELSIF p_kind = 'easter_offset' THEN
      v_offset := (p_params->>'offset')::int;
      IF v_offset IS NULL OR v_offset NOT BETWEEN -120 AND 120 THEN RETURN false; END IF;
      RETURN coalesce(p_params->>'calendar', 'western') IN ('western', 'orthodox');
    ELSIF p_kind = 'nth_weekday' THEN
      v_month := (p_params->>'month')::int; v_weekday := (p_params->>'weekday')::int; v_n := (p_params->>'n')::int;
      RETURN coalesce(v_month BETWEEN 1 AND 12 AND v_weekday BETWEEN 1 AND 7 AND (v_n BETWEEN 1 AND 5 OR v_n = -1), false);
    END IF;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN false;
  END;
  RETURN false;
END;
$$;

-- Húsvétvasárnap: nyugati (Meeus/Jones/Butcher) vagy ortodox (Julián-számítás, Gergely-naptárra váltva).
CREATE OR REPLACE FUNCTION public.calendar_easter_date(p_year int, p_calendar text DEFAULT 'western')
RETURNS date LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE a int; b int; c int; d int; e int; f int; g int; h int; i int; k int; l int; m int;
BEGIN
  IF p_year IS NULL OR p_year NOT BETWEEN 1900 AND 2199 THEN RAISE EXCEPTION 'calendar_year_out_of_range'; END IF;
  IF p_calendar = 'orthodox' THEN
    a := p_year % 4; b := p_year % 7; c := p_year % 19;
    d := (19 * c + 15) % 30;
    e := (2 * a + 4 * b - d + 34) % 7;
    RETURN make_date(p_year, (d + e + 114) / 31, ((d + e + 114) % 31) + 1)
      + (p_year / 100 - p_year / 400 - 2);
  END IF;
  a := p_year % 19; b := p_year / 100; c := p_year % 100;
  d := b / 4; e := b % 4; f := (b + 8) / 25; g := (b - f + 1) / 3;
  h := (19 * a + b - d - g + 15) % 30;
  i := c / 4; k := c % 4;
  l := (32 + 2 * e + 2 * i - h - k) % 7;
  m := (a + 11 * h + 22 * l) / 451;
  RETURN make_date(p_year, (h + l - 7 * m + 114) / 31, ((h + l - 7 * m + 114) % 31) + 1);
END;
$$;

-- Egy szabály adott évi előfordulása (explicit szabálynál és nem létező napnál üres).
CREATE OR REPLACE FUNCTION public.calendar_rule_occurrence(p_kind text, p_params jsonb, p_duration int, p_year int)
RETURNS TABLE (earliest date, latest date) LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE
  v_start date; v_end date; v_first date; v_last date; v_month int; v_day int; v_em int; v_ed int;
  v_weekday int; v_n int; v_end_year int;
BEGIN
  IF p_kind = 'explicit' OR NOT public.calendar_rule_params_valid(p_kind, p_params) THEN RETURN; END IF;
  IF p_kind = 'fixed_annual' THEN
    v_month := (p_params->>'month')::int; v_day := (p_params->>'day')::int;
    v_last := (make_date(p_year, v_month, 1) + interval '1 month' - interval '1 day')::date;
    IF v_day > extract(day FROM v_last)::int THEN RETURN; END IF; -- pl. febr. 29. nem szökőévben
    v_start := make_date(p_year, v_month, v_day);
    IF p_params ? 'end_month' THEN
      v_em := (p_params->>'end_month')::int; v_ed := (p_params->>'end_day')::int;
      v_end_year := CASE WHEN (v_em, v_ed) >= (v_month, v_day) THEN p_year ELSE p_year + 1 END;
      v_last := (make_date(v_end_year, v_em, 1) + interval '1 month' - interval '1 day')::date;
      v_end := make_date(v_end_year, v_em, least(v_ed, extract(day FROM v_last)::int));
    END IF;
  ELSIF p_kind = 'easter_offset' THEN
    v_start := public.calendar_easter_date(p_year, coalesce(p_params->>'calendar', 'western'))
      + (p_params->>'offset')::int;
  ELSIF p_kind = 'nth_weekday' THEN
    v_month := (p_params->>'month')::int; v_weekday := (p_params->>'weekday')::int; v_n := (p_params->>'n')::int;
    v_first := make_date(p_year, v_month, 1);
    v_last := (v_first + interval '1 month' - interval '1 day')::date;
    IF v_n = -1 THEN
      v_start := v_last - ((extract(isodow FROM v_last)::int - v_weekday + 7) % 7);
    ELSE
      v_start := v_first + ((v_weekday - extract(isodow FROM v_first)::int + 7) % 7) + 7 * (v_n - 1);
      IF v_start > v_last THEN RETURN; END IF;
    END IF;
  ELSE
    RETURN;
  END IF;
  earliest := v_start;
  latest := coalesce(v_end, v_start + (greatest(coalesce(p_duration, 1), 1) - 1));
  RETURN NEXT;
END;
$$;

-- ============================================================================
-- 3. Törzstáblák
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ref_calendar_period_types (
  key             varchar(40)  PRIMARY KEY CHECK (key ~ '^[a-z0-9_]+$'),
  label_localized jsonb        NOT NULL CHECK (public.calendar_label_valid(label_localized)),
  can_be_day_off  boolean      NOT NULL DEFAULT false,
  icon_key        varchar(50),
  sort_order      integer      NOT NULL DEFAULT 999,
  status          varchar(10)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.ref_calendar_period_types IS 'M23: időszaktípusok katalógusa (FR-M23-001)';

CREATE TABLE IF NOT EXISTS public.ref_calendar_tags (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  key             varchar(40)  NOT NULL UNIQUE CHECK (key ~ '^[a-z0-9_]+$'),
  label_localized jsonb        NOT NULL CHECK (public.calendar_label_valid(label_localized)),
  icon_key        varchar(50)  CHECK (icon_key IS NULL OR icon_key ~ '^[a-z0-9-]+$'),
  color_token     varchar(40)  CHECK (color_token IS NULL OR color_token ~ '^[a-z][a-z0-9-]*$'),
  sort_order      integer      NOT NULL DEFAULT 999,
  status          varchar(10)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  updated_by      uuid         REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.ref_calendar_tags IS 'M23: szabadon bővíthető címkék (FR-M23-002); a kulcs létrehozás után nem módosítható';

CREATE TABLE IF NOT EXISTS public.ref_calendar_periods (
  id                    uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  key                   varchar(80)  NOT NULL CHECK (key ~ '^[a-z0-9_]+$'),
  label_localized       jsonb        NOT NULL CHECK (public.calendar_label_valid(label_localized)),
  description_localized jsonb        CHECK (description_localized IS NULL OR jsonb_typeof(description_localized) = 'object'),
  period_type           varchar(40)  NOT NULL REFERENCES public.ref_calendar_period_types(key),
  country_code          varchar(2)   REFERENCES public.ref_countries(code),
  subdivision_code      varchar(10)  CHECK (subdivision_code IS NULL OR subdivision_code ~ '^[A-Z]{2}-[A-Z0-9]{1,3}$'),
  hemisphere            varchar(5)   CHECK (hemisphere IS NULL OR hemisphere IN ('north', 'south')),
  rule_kind             varchar(20)  NOT NULL CHECK (rule_kind IN ('fixed_annual', 'easter_offset', 'nth_weekday', 'explicit')),
  rule_params           jsonb        NOT NULL DEFAULT '{}'::jsonb,
  duration_days         smallint     CHECK (duration_days IS NULL OR duration_days BETWEEN 1 AND 366),
  is_day_off            boolean      NOT NULL DEFAULT false,
  source_text           text         NOT NULL CHECK (length(trim(source_text)) > 0),
  source_url            text         CHECK (source_url IS NULL OR source_url ~ '^https?://'),
  status                varchar(10)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  updated_by            uuid         REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at            timestamptz  NOT NULL DEFAULT now(),
  updated_at            timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT uq_ref_calendar_periods_scope_key UNIQUE NULLS NOT DISTINCT (country_code, subdivision_code, key),
  CONSTRAINT chk_ref_calendar_periods_hemisphere CHECK (hemisphere IS NULL OR period_type = 'season'),
  CONSTRAINT chk_ref_calendar_periods_subdivision CHECK (
    subdivision_code IS NULL OR (country_code IS NOT NULL AND left(subdivision_code, 2) = country_code)
  ),
  -- BR-M23-001: országfüggetlen csak az évszak és az egyedi időszak lehet
  CONSTRAINT chk_ref_calendar_periods_country CHECK (country_code IS NOT NULL OR period_type IN ('season', 'custom')),
  CONSTRAINT chk_ref_calendar_periods_rule CHECK (public.calendar_rule_params_valid(rule_kind, rule_params))
);
COMMENT ON TABLE public.ref_calendar_periods IS 'M23: időszak-definíciók országhoz / országrészhez, szabállyal vagy évenkénti előfordulással (FR-M23-003)';
COMMENT ON COLUMN public.ref_calendar_periods.rule_params IS
  'fixed_annual: {month, day[, end_month, end_day]} · easter_offset: {offset, calendar: western|orthodox} · nth_weekday: {month, weekday: 1=hétfő..7=vasárnap, n: 1..5 | -1 = utolsó} · explicit: {[one_off: true] = egyszeri, nem hiányzik a következő évből}';

CREATE TABLE IF NOT EXISTS public.ref_calendar_occurrences (
  id           uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  period_id    uuid         NOT NULL REFERENCES public.ref_calendar_periods(id) ON DELETE CASCADE,
  year         smallint     NOT NULL CHECK (year BETWEEN 1900 AND 2199),
  earliest     date         NOT NULL,
  latest       date         NOT NULL,
  status       varchar(10)  NOT NULL DEFAULT 'entered' CHECK (status IN ('generated', 'entered', 'verified')),
  verified_by  uuid         REFERENCES public.profiles(id) ON DELETE SET NULL,
  verified_at  timestamptz,
  source_note  text,
  created_at   timestamptz  NOT NULL DEFAULT now(),
  updated_at   timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT uq_ref_calendar_occurrences_period_year UNIQUE (period_id, year),
  CONSTRAINT chk_ref_calendar_occurrences_range CHECK (latest >= earliest AND latest - earliest <= 366),
  -- EC-01: az évfordulón átnyúló előfordulás éve a kezdő év
  CONSTRAINT chk_ref_calendar_occurrences_year CHECK (year = extract(year FROM earliest)::int)
);
COMMENT ON TABLE public.ref_calendar_occurrences IS 'M23: egy definíció adott évi dátumintervalluma (FR-M23-004); generated = szabályból, entered = kézzel, verified = forrással ellenőrizve';

CREATE TABLE IF NOT EXISTS public.ref_calendar_period_tags (
  period_id  uuid        NOT NULL REFERENCES public.ref_calendar_periods(id) ON DELETE CASCADE,
  tag_id     uuid        NOT NULL REFERENCES public.ref_calendar_tags(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (period_id, tag_id)
);
COMMENT ON TABLE public.ref_calendar_period_tags IS 'M23: definíció–címke kapcsolat (FR-M23-002 2.)';

CREATE INDEX IF NOT EXISTS idx_ref_calendar_periods_country ON public.ref_calendar_periods (country_code, status);
CREATE INDEX IF NOT EXISTS idx_ref_calendar_periods_type ON public.ref_calendar_periods (period_type);
CREATE INDEX IF NOT EXISTS idx_ref_calendar_occurrences_range ON public.ref_calendar_occurrences (earliest, latest);
CREATE INDEX IF NOT EXISTS idx_ref_calendar_occurrences_period ON public.ref_calendar_occurrences (period_id);
CREATE INDEX IF NOT EXISTS idx_ref_calendar_period_tags_tag ON public.ref_calendar_period_tags (tag_id);

-- updated_at és a kulcs változatlansága
CREATE OR REPLACE FUNCTION public.calendar_touch_updated_at()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.calendar_guard_key()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW.key IS DISTINCT FROM OLD.key THEN
    RAISE EXCEPTION 'calendar_key_immutable' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ref_calendar_period_types_touch ON public.ref_calendar_period_types;
CREATE TRIGGER trg_ref_calendar_period_types_touch BEFORE UPDATE ON public.ref_calendar_period_types
  FOR EACH ROW EXECUTE FUNCTION public.calendar_touch_updated_at();
DROP TRIGGER IF EXISTS trg_ref_calendar_tags_touch ON public.ref_calendar_tags;
CREATE TRIGGER trg_ref_calendar_tags_touch BEFORE UPDATE ON public.ref_calendar_tags
  FOR EACH ROW EXECUTE FUNCTION public.calendar_touch_updated_at();
DROP TRIGGER IF EXISTS trg_ref_calendar_periods_touch ON public.ref_calendar_periods;
CREATE TRIGGER trg_ref_calendar_periods_touch BEFORE UPDATE ON public.ref_calendar_periods
  FOR EACH ROW EXECUTE FUNCTION public.calendar_touch_updated_at();
DROP TRIGGER IF EXISTS trg_ref_calendar_occurrences_touch ON public.ref_calendar_occurrences;
CREATE TRIGGER trg_ref_calendar_occurrences_touch BEFORE UPDATE ON public.ref_calendar_occurrences
  FOR EACH ROW EXECUTE FUNCTION public.calendar_touch_updated_at();

DROP TRIGGER IF EXISTS trg_ref_calendar_period_types_key ON public.ref_calendar_period_types;
CREATE TRIGGER trg_ref_calendar_period_types_key BEFORE UPDATE ON public.ref_calendar_period_types
  FOR EACH ROW EXECUTE FUNCTION public.calendar_guard_key();
DROP TRIGGER IF EXISTS trg_ref_calendar_tags_key ON public.ref_calendar_tags;
CREATE TRIGGER trg_ref_calendar_tags_key BEFORE UPDATE ON public.ref_calendar_tags
  FOR EACH ROW EXECUTE FUNCTION public.calendar_guard_key();
DROP TRIGGER IF EXISTS trg_ref_calendar_periods_key ON public.ref_calendar_periods;
CREATE TRIGGER trg_ref_calendar_periods_key BEFORE UPDATE ON public.ref_calendar_periods
  FOR EACH ROW EXECUTE FUNCTION public.calendar_guard_key();

-- ============================================================================
-- 4. RLS (11. fejezet) — mind a négy művelethez explicit szabály
-- ============================================================================

ALTER TABLE public.ref_calendar_period_types ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ref_calendar_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ref_calendar_periods ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ref_calendar_occurrences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ref_calendar_period_tags ENABLE ROW LEVEL SECURITY;

-- Időszaktípusok
DROP POLICY IF EXISTS ref_calendar_period_types_select ON public.ref_calendar_period_types;
CREATE POLICY ref_calendar_period_types_select ON public.ref_calendar_period_types
  FOR SELECT USING (status = 'active' OR public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_period_types_insert ON public.ref_calendar_period_types;
CREATE POLICY ref_calendar_period_types_insert ON public.ref_calendar_period_types
  FOR INSERT WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_period_types_update ON public.ref_calendar_period_types;
CREATE POLICY ref_calendar_period_types_update ON public.ref_calendar_period_types
  FOR UPDATE USING (public.is_calendar_admin()) WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_period_types_delete ON public.ref_calendar_period_types;
CREATE POLICY ref_calendar_period_types_delete ON public.ref_calendar_period_types
  FOR DELETE USING (false); -- BR-M23-009: inaktiválás törlés helyett

-- Címkék
DROP POLICY IF EXISTS ref_calendar_tags_select ON public.ref_calendar_tags;
CREATE POLICY ref_calendar_tags_select ON public.ref_calendar_tags
  FOR SELECT USING (status = 'active' OR public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_tags_insert ON public.ref_calendar_tags;
CREATE POLICY ref_calendar_tags_insert ON public.ref_calendar_tags
  FOR INSERT WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_tags_update ON public.ref_calendar_tags;
CREATE POLICY ref_calendar_tags_update ON public.ref_calendar_tags
  FOR UPDATE USING (public.is_calendar_admin()) WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_tags_delete ON public.ref_calendar_tags;
CREATE POLICY ref_calendar_tags_delete ON public.ref_calendar_tags
  FOR DELETE USING (false);

-- Időszak-definíciók
DROP POLICY IF EXISTS ref_calendar_periods_select ON public.ref_calendar_periods;
CREATE POLICY ref_calendar_periods_select ON public.ref_calendar_periods
  FOR SELECT USING (status = 'active' OR public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_periods_insert ON public.ref_calendar_periods;
CREATE POLICY ref_calendar_periods_insert ON public.ref_calendar_periods
  FOR INSERT WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_periods_update ON public.ref_calendar_periods;
CREATE POLICY ref_calendar_periods_update ON public.ref_calendar_periods
  FOR UPDATE USING (public.is_calendar_admin()) WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_periods_delete ON public.ref_calendar_periods;
