-- Előfordulások: publikusan csak a generated/verified sor, aktív definícióval (NyK-05)
DROP POLICY IF EXISTS ref_calendar_occurrences_select ON public.ref_calendar_occurrences;
CREATE POLICY ref_calendar_occurrences_select ON public.ref_calendar_occurrences
  FOR SELECT USING (
    public.is_calendar_admin()
    OR (
      status IN ('generated', 'verified')
      AND EXISTS (
        SELECT 1 FROM public.ref_calendar_periods p
        WHERE p.id = ref_calendar_occurrences.period_id AND p.status = 'active'
      )
    )
  );
DROP POLICY IF EXISTS ref_calendar_occurrences_insert ON public.ref_calendar_occurrences;
CREATE POLICY ref_calendar_occurrences_insert ON public.ref_calendar_occurrences
  FOR INSERT WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_occurrences_update ON public.ref_calendar_occurrences;
CREATE POLICY ref_calendar_occurrences_update ON public.ref_calendar_occurrences
  FOR UPDATE USING (public.is_calendar_admin()) WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_occurrences_delete ON public.ref_calendar_occurrences;
CREATE POLICY ref_calendar_occurrences_delete ON public.ref_calendar_occurrences
  FOR DELETE USING (public.is_calendar_admin());

-- Definíció–címke
DROP POLICY IF EXISTS ref_calendar_period_tags_select ON public.ref_calendar_period_tags;
CREATE POLICY ref_calendar_period_tags_select ON public.ref_calendar_period_tags
  FOR SELECT USING (
    public.is_calendar_admin()
    OR (
      EXISTS (SELECT 1 FROM public.ref_calendar_periods p WHERE p.id = ref_calendar_period_tags.period_id AND p.status = 'active')
      AND EXISTS (SELECT 1 FROM public.ref_calendar_tags t WHERE t.id = ref_calendar_period_tags.tag_id AND t.status = 'active')
    )
  );
DROP POLICY IF EXISTS ref_calendar_period_tags_insert ON public.ref_calendar_period_tags;
CREATE POLICY ref_calendar_period_tags_insert ON public.ref_calendar_period_tags
  FOR INSERT WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_period_tags_update ON public.ref_calendar_period_tags;
CREATE POLICY ref_calendar_period_tags_update ON public.ref_calendar_period_tags
  FOR UPDATE USING (public.is_calendar_admin()) WITH CHECK (public.is_calendar_admin());
DROP POLICY IF EXISTS ref_calendar_period_tags_delete ON public.ref_calendar_period_tags;
CREATE POLICY ref_calendar_period_tags_delete ON public.ref_calendar_period_tags
  FOR DELETE USING (public.is_calendar_admin());

-- ============================================================================
-- 5. Előfordulások generálása (FR-M23-004 1., EC-02, EC-08)
-- ============================================================================
-- SECURITY INVOKER: az RLS érvényes, nem admin hívó nem ír. A meglévő generated sort frissíti,
-- ha a szabály változott; az entered/verified sort sosem írja felül. Visszatérés: érintett sorok.
CREATE OR REPLACE FUNCTION public.calendar_generate_occurrences(p_from_year int, p_to_year int, p_period_id uuid DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE v_count integer;
BEGIN
  IF p_from_year IS NULL OR p_to_year IS NULL OR p_to_year < p_from_year OR p_to_year - p_from_year > 10 THEN
    RAISE EXCEPTION 'calendar_invalid_year_range' USING ERRCODE = '22023';
  END IF;
  WITH src AS (
    SELECT p.id AS period_id, y.y AS year, r.earliest AS r_earliest, r.latest AS r_latest
    FROM public.ref_calendar_periods p
    CROSS JOIN generate_series(p_from_year, p_to_year) AS y(y)
    CROSS JOIN LATERAL public.calendar_rule_occurrence(p.rule_kind, p.rule_params, p.duration_days, y.y) AS r
    WHERE p.status = 'active' AND p.rule_kind <> 'explicit'
      AND (p_period_id IS NULL OR p.id = p_period_id)
  ), upserted AS (
    SELECT s.period_id, s.year, s.r_earliest, s.r_latest, 'generated', 'rule' FROM src s
    ON CONFLICT (period_id, year) DO UPDATE
      SET earliest = EXCLUDED.earliest, latest = EXCLUDED.latest
      WHERE o.status = 'generated'
        AND (o.earliest, o.latest) IS DISTINCT FROM (EXCLUDED.earliest, EXCLUDED.latest)
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM upserted;
  RETURN v_count;
END;
$$;
REVOKE ALL ON FUNCTION public.calendar_generate_occurrences(int, int, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calendar_generate_occurrences(int, int, uuid) TO authenticated, service_role;

